package village.vale.arenas;

import com.google.gson.*;
import java.util.*;
import net.minecraft.entity.*;
import net.minecraft.entity.player.EntityPlayerMP;
import net.minecraft.init.Items;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.util.*;
import net.minecraft.util.math.*;
import net.minecraft.world.*;
import net.minecraftforge.common.*;
import net.minecraftforge.event.entity.living.*;
import net.minecraftforge.fml.common.eventhandler.*;

/** Targeted actual normal native Gaara finisher, with production authority.
 * Native damage API scope only: not client weapon range, cooldown or a cast. */
public final class GaaraTerminalNativeChecks {
 private static MinecraftServer server;private static EntityPlayerMP player;private static ArenaDirector.Definition arena;private static EntityLivingBase boss;
 private static JsonObject report;private static JsonArray failures,attempts,loot;private static JsonObject run;private static LivingDeathEvent death;private static int stage,wait,ticks,attacks,startBody;private static boolean done;
 private static final Observer observer=new Observer();
 private GaaraTerminalNativeChecks(){}
 private static void check(boolean ok,String why){if(!ok)throw new IllegalStateException(why);}
 private static void guide(int[] at){NativeProbe.prewarm(server.getWorld(0),new BlockPos(at[0],at[1],at[2]));ArenaDirector.move(player,at);server.getWorld(0).getPlayerChunkMap().updateMovingPlayer(player);}
 private static void click(int node){int[] p=arena.nodes[node];boolean found=false;for(int[] off:new int[][]{{0,-3},{0,3},{-3,0},{3,0}}){int[] at={p[0]+off[0],arena.floor,p[2]+off[1]};NativeProbe.prewarm(server.getWorld(0),new BlockPos(at[0],at[1],at[2]));if(ArenaDirector.safe(server.getWorld(0),at)){guide(at);found=true;break;}}check(found,"No actual physical introduction approach");ForgeHooks.onRightClickBlock(player,EnumHand.MAIN_HAND,new BlockPos(p[0],p[1],p[2]),EnumFacing.UP,new Vec3d(p[0]+.5,p[1]+.5,p[2]+.5));}
 public static void begin(MinecraftServer s,List<ArenaDirector.Definition> definitions,EntityPlayerMP p){
  check(Boolean.getBoolean("hbv.arenas.nativeProbe")&&Boolean.getBoolean("hbv.arenas.gaaraOnly")&&s.getPlayerList().getPlayerByUUID(p.getUniqueID())==p,"Targeted private native guard");server=s;player=p;arena=null;for(ArenaDirector.Definition d:definitions)if(d.boss.equals("narutomod:gaara"))arena=d;check(arena!=null,"Exact Gaara definition absent");report=new JsonObject();failures=new JsonArray();attempts=new JsonArray();loot=new JsonArray();report.add("failures",failures);report.add("native_damage_attempts",attempts);report.add("actual_native_drop_xp_events",loot);report.addProperty("scope","ACTUAL_NORMAL_NATIVE_GAARA_FINISHER_PRODUCTION_POLICY_AND_EARNED_OUTBOX; direct native damage API, no client weapon/cast claim");report.addProperty("startup_admission_policy",arena.terminal_verified);report.addProperty("startup_native_death_policy",arena.native_death_verified);check(arena.terminal_verified&&arena.native_death_verified&&NativeBossPolicies.nativeDeathAccepted(arena),"Actual production native-death authority unavailable");check(!s.getPlayerList().canSendCommands(p.getGameProfile()),"Targeted player unexpectedly operator");stage=wait=ticks=attacks=0;done=false;death=null;boss=null;run=null;MinecraftForge.EVENT_BUS.register(observer);
 }
 private static double nativeXp(){try{return ((Number)Class.forName("net.narutomod.PlayerTracker").getMethod("getBattleXp",net.minecraft.entity.player.EntityPlayer.class).invoke(null,player)).doubleValue();}catch(ReflectiveOperationException missing){throw new IllegalStateException("Actual native XP observer unavailable",missing);}}
 private static void defend(){if(boss==null||!boss.isEntityAlive()||!player.isEntityAlive())return;double dx=boss.posX-player.posX,dz=boss.posZ-player.posZ;player.rotationYaw=(float)Math.toDegrees(Math.atan2(-dx,dz));player.rotationPitch=0;if(!player.isHandActive())player.setActiveHand(EnumHand.OFF_HAND);}
 public static boolean tick(){if(done)return true;defend();if(--wait>0)return false;try{check(++ticks<700,"Targeted native terminal bounded budget exceeded");check(player.isEntityAlive()&&server.getPlayerList().getPlayerByUUID(player.getUniqueID())==player,"Official vulnerable participant died or changed");
  if(stage==0){player.setGameType(GameType.SURVIVAL);for(ArenaDirector.Definition d:ArenaDirector.DEFINITIONS){JsonObject r=ArenaDirector.run(d);check(r==null||!r.getAsJsonObject("members").has(player.getUniqueID().toString()),"Pre-existing membership preserved");}player.setItemStackToSlot(net.minecraft.inventory.EntityEquipmentSlot.OFFHAND,new ItemStack(Items.SHIELD));ArenaIntro.start(player,arena);click(0);stage=1;wait=3;return false;}
  if(stage==1){click(1);stage=2;wait=3;return false;}
  if(stage==2){check(ArenaIntro.complete(player,arena),"Actual physical intro incomplete");server.getCommandManager().executeCommand(player,"narutoarena enter "+arena.id);run=ArenaDirector.run(arena);check(run!=null&&ArenaDirector.text(run,"state").equals("PHASE1"),"Actual nonoperator normal admission failed");Entity actual=server.getWorld(0).getEntityFromUuid(UUID.fromString(ArenaDirector.text(run,"boss_uuid")));check(actual instanceof EntityLivingBase,"Exact native body missing");boss=(EntityLivingBase)actual;report.addProperty("native_battle_xp_before",nativeXp());report.addProperty("vanilla_experience_before",player.experienceTotal);report.addProperty("run_uuid",ArenaDirector.text(run,"run"));report.addProperty("boss_uuid",boss.getUniqueID().toString());report.addProperty("native_class",boss.getClass().getName());report.addProperty("native_class_sha256",ArenaTerminals.classHash(boss));startBody=boss.ticksExisted;guide(new int[]{(int)Math.floor(boss.posX)+2,arena.floor,(int)Math.floor(boss.posZ)});stage=3;wait=22;return false;}
  if(stage==3){check(boss.ticksExisted>startBody,"Actual native Gaara did not update");if(!boss.isEntityAlive()){stage=4;wait=1;return false;}check(attacks++<12,"Original provider rejected all bounded native player contacts");JsonObject attempt=new JsonObject();float hp=boss.getHealth();attempt.addProperty("health_before",hp);attempt.addProperty("absorption_before",boss.getAbsorptionAmount());attempt.addProperty("amount",1000F);player.resetActiveHand();boolean accepted=boss.attackEntityFrom(DamageSource.causePlayerDamage(player),1000F);attempt.addProperty("native_return",accepted);attempt.addProperty("health_after_unwind",boss.getHealth());attempt.addProperty("actual_health_loss",Math.max(0,hp-boss.getHealth()));attempts.add(attempt);stage=boss.isEntityAlive()?3:4;wait=22;return false;}
  if(stage==4){check(death!=null&&!death.isCanceled()&&death.getSource().getTrueSource()==player&&death.getEntityLiving()==boss,"Final native player death event not accepted");if(!ArenaDirector.text(run,"state").equals("REWARD_PENDING")){check(!ArenaDirector.text(run,"state").equals("SAFE_CLOSED"),"Native terminal safety closed");wait=1;return false;}check(server.getWorld(0).getEntityFromUuid(boss.getUniqueID())==null,"Native body still present");check(ArenaDirector.number(run,"quiet")>=120,"Actual loaded native absence observation incomplete");JsonObject member=run.getAsJsonObject("members").getAsJsonObject(player.getUniqueID().toString());check(member.get("contribution").getAsDouble()==1,"Exact native finisher contribution missing or duplicated");check(!run.has("objectives")||run.getAsJsonObject("objectives").size()==0,"Targeted native lethal fabricated physical objectives");report.addProperty("native_battle_xp_after",nativeXp());report.addProperty("vanilla_experience_after",player.experienceTotal);report.addProperty("native_battle_xp_delta",nativeXp()-report.get("native_battle_xp_before").getAsDouble());report.addProperty("accepted_uncancelled_native_player_death",true);report.addProperty("actual_native_quiet_ticks",ArenaDirector.number(run,"quiet"));report.addProperty("native_body_removed_without_direct_cleanup",true);report.addProperty("physical_sequences_skipped_by_valid_native_finisher",true);guide(arena.reward);check(RewardOutbox.deliver(player,run,0),"Genuine earned native reward did not deliver");NBTTagList after=player.inventory.writeToNBT(new NBTTagList());check(RewardOutbox.deliver(player,run,0)&&after.equals(player.inventory.writeToNBT(new NBTTagList())),"Actual earned reward replay changed inventory");report.addProperty("real_earned_native_reward_and_replay",true);server.getCommandManager().executeCommand(player,"narutoarena exit");stage=5;wait=3;return false;}
  if(stage==5){if(!ArenaDirector.text(run,"state").equals("AVAILABLE")){check(ArenaDirector.text(run,"state").equals("RESET_READY"),"Native return not reset-ready");wait=1;return false;}report.addProperty("nonoperator_automatic_reset",true);report.addProperty("drop_xp_policy","Exact normal body is excluded from preview suppression; all actually emitted Forge drop/XP events retained below");finish();return true;}
 }catch(Throwable failure){failures.add(failure.toString());report.addProperty("failed_stage",stage);finish();return true;}return false;}
 private static void finish(){MinecraftForge.EVENT_BUS.unregister(observer);report.addProperty("passed",failures.size()==0);report.addProperty("native_body_ticks",boss==null?0:boss.ticksExisted-startBody);report.addProperty("health_setters_or_boss_immunity",false);done=true;}
 public static JsonObject result(){return report;}
 public static EntityPlayerMP currentPlayer(){return player;}
 public static final class Observer {
  @SubscribeEvent(priority=EventPriority.LOWEST,receiveCanceled=true)public void died(LivingDeathEvent e){if(e.getEntityLiving()==boss)death=e;}
  @SubscribeEvent(priority=EventPriority.LOWEST,receiveCanceled=true)public void drops(LivingDropsEvent e){if(e.getEntityLiving()!=boss)return;JsonObject row=new JsonObject();row.addProperty("kind","LivingDropsEvent");row.addProperty("count",e.getDrops().size());row.addProperty("cancelled",e.isCanceled());loot.add(row);}
  @SubscribeEvent(priority=EventPriority.LOWEST)public void xp(LivingExperienceDropEvent e){if(e.getEntityLiving()!=boss)return;JsonObject row=new JsonObject();row.addProperty("kind","LivingExperienceDropEvent");row.addProperty("xp",e.getDroppedExperience());loot.add(row);}
 }
}
